package localui

import (
	"html/template"
	"io"
	"strings"
)

func writeHTML(w io.Writer, j *Job) error {
	// Preview data is generated by our JPEG encoder; do not trust arbitrary URLs.
	images := map[string]template.URL{}
	for _, im := range j.Images {
		if strings.HasPrefix(im.Data, "data:image/jpeg;base64,") {
			images[im.File] = template.URL(im.Data)
		}
	}
	view := struct {
		*Job
		Previews map[string]template.URL
	}{Job: j, Previews: images}
	return exportTemplate.Execute(w, view)
}

var exportTemplate = template.Must(template.New("report").Parse(`<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'; base-uri 'none'">
<title>Greenlight preflight report</title><style>body{font:15px system-ui,sans-serif;background:#f6f7f3;color:#243029;max-width:960px;margin:3rem auto;padding:0 1.5rem}h1{font-size:38px;letter-spacing:-1.5px}header{border-bottom:1px solid #dfe3d9;padding-bottom:2rem}article{border-bottom:1px solid #dfe3d9;padding:1.5rem 0}h2{font-size:18px}p,li{line-height:1.6}small,code{color:#6e786f}code{display:block;overflow-wrap:anywhere;font-size:11px}img{max-width:260px;width:100%;margin-top:1rem}.status{font-size:12px;text-transform:uppercase}.passed{color:#4b7434}.failed{color:#a8503d}.suspected{color:#997637}.unverified{color:#6e786f}footer{padding:2rem 0;font-size:12px}a{color:#476637}</style>
<p>Confidence describes each check’s evidence, not rejection probability. Missing evidence does not establish a broken feature.</p><header><small>GREENLIGHT · LOCAL PREFLIGHT</small><h1>{{.Summary.Verdict}}</h1><p>{{.Scope}}</p><p>{{.Summary.Checked}} / {{.Summary.Applicable}} applicable checks evaluated · {{.Summary.Failed}} failed · {{.Summary.Suspected}} need review · {{.Summary.Unverified}} unverified</p><small>{{.Started.Format "2006-01-02 15:04:05 MST"}} · Approval remains Apple's decision.</small>{{if .ReleaseBinding}}<p><code>Ruleset: {{.Ruleset}}<br>Binding: {{.ReleaseBinding}}<br>Artifact SHA-256: {{.ArtifactSHA256}}</code></p>{{end}}</header>
{{range .Rows}}<article><span class="status {{.Status}}">{{.Status}} · {{.Group}}</span><h2>{{.Title}}</h2><p>{{.Evidence}}</p><p><small>{{if eq .Confidence "none"}}Insufficient evidence{{else}}{{.Confidence}} confidence{{end}} · {{.ConfidenceReason}}</small></p>{{if .File}}<code>{{.File}}</code>{{end}}{{if .Fix}}<p><strong>Suggested next step:</strong> {{.Fix}}</p>{{end}}{{if .Guideline}}<p><a href="{{.Guideline}}">Policy source</a></p>{{end}}{{if .Regions}}{{with index $.Previews .File}}<img src="{{.}}" alt="Screenshot evidence">{{end}}{{end}}<small>{{.Confidence}} confidence</small></article>{{end}}
<footer><h2>Scope</h2><ul>{{range .Limitations}}<li>{{.}}</li>{{end}}</ul>RandyVentures / Greenlight · MIT</footer></html>`))
